class RPGCharacter:
    MAX_HP = 100
    HEAL_AMOUNT = 10
    MAX_LEVEL = 100
    HP_PER_LEVEL = 20
    ATTACK_PER_LEVEL = 5
    DEFENSE_PER_LEVEL = 5
    EXP_PER_LEVEL = 100

    def __init__(self, name, hp, attack_power, defense, level=1):
        self._name = name
        self.hp = hp
        self.attack_power = attack_power
        self.defense = defense
        self.level = level
        self.exp = 0

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    def attack(self, other_character):
        damage = self._calculate_damage(other_character.defense)
        other_character.hp -= damage

    def _calculate_damage(self, other_defense):
        return max(self.attack_power - other_defense, 1)

    def heal(self):
        self.hp = min(self.hp + self.HEAL_AMOUNT, self.MAX_HP)
        return self.hp

    def gain_exp(self, amount):
        amount = self._add_experience(amount)

    def _add_experience(self, amount):
        while amount != 0:
            exp_to_level_up = self.level * self.EXP_PER_LEVEL - self.exp
            if amount >= exp_to_level_up:
                amount -= exp_to_level_up
                self.level_up()
            else:
                self.exp += amount
                amount = 0
        return amount

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.hp += self.HP_PER_LEVEL
            self.attack_power += self.ATTACK_PER_LEVEL
            self.defense += self.DEFENSE_PER_LEVEL
        return self.level, self.hp, self.attack_power, self.defense

    def is_alive(self):
        return self.hp > 0
